package mz.bam.seeky.android;
import android.app.*;import android.widget.*;
final class StudyCapture {
 static void choose(ReaderActivity a,long material,int segment,String selection){new UiDialog.Builder(a).setTitle("Estudar esta passagem").setItems(new String[]{"Guardar como anotação","Criar cartão de pergunta e resposta","Criar cartão de lacuna"},(d,i)->form(a,material,segment,selection,i)).setNegativeButton("Cancelar",null).show();}
 static void form(ReaderActivity a,long material,int part,String text,int type){LinearLayout wrap=new LinearLayout(a);wrap.setOrientation(1);EditText title=new EditText(a),body=new EditText(a);title.setHint(type==0?"Título da anotação":"Pergunta / frente do cartão");title.setMinLines(2);body.setHint(type==0?"Apontamento":"Resposta / verso do cartão");body.setMinLines(4);body.setText(text);if(type==2)title.setText(AppLanguage.text(title.getContext(),"Complete a lacuna: [...]"));wrap.addView(title);wrap.addView(body);TextView hint=a.text("Ligado ao material e à página/capítulo de origem. Preencha a pergunta com as suas palavras.",12);wrap.addView(hint);AlertDialog dialog=new UiDialog.Builder(a).setTitle(type==0?"Anotação em Estudos":"Cartão em Estudos").setView(wrap).setPositiveButton("Guardar",null).setNegativeButton("Cancelar",null).create();dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String front=StudySchedule.valid(title.getText().toString(),type==0?200:5000,"Título / pergunta"),back=StudySchedule.valid(body.getText().toString(),type==0?200000:20000,"Conteúdo");dialog.dismiss();a.worker.execute(()->{try(StudyStore db=new StudyStore(a)){StudyStore.Row source=db.get("materials",material);if(source==null)throw new IllegalStateException("Material já não disponível em Estudos.");long now=System.currentTimeMillis();if(type==0)db.save("notes",0,StudyStore.values("subject",source.n("subject"),"material",material,"segment",part,"title",front,"body",back,"created",now,"updated",now));else db.save("cards",0,StudyStore.values("subject",source.n("subject"),"material",material,"segment",part,"front",front,"back",back,"due",now,"updated",now));a.ui(()->Toast.makeText(a,"Guardado em Estudos.",Toast.LENGTH_LONG).show());}catch(Exception e){a.ui(()->new UiDialog.Builder(a).setTitle("Guardar em Estudos").setMessage(e.getMessage()).setPositiveButton("Fechar",null).show());}});}catch(Exception e){Toast.makeText(a,e.getMessage(),Toast.LENGTH_LONG).show();}});}
}
